import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv2d kernel specialized for AlexNet conv1:
//   Cin=3, KH=KW=11, stride=4, padding=2  (e.g. 224x224 -> 55x55)
//
// Each thread block cooperatively computes a tile of output pixels for
// CcPerBlock output channels. The (small) filter slices for those output
// channels are staged in shared memory once and reused by all threads.
template <typename T, int Cin, int KH, int KW>
__global__ void conv2d_11x11_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int H, int Win,
    int Cout,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;   // output pixels per thread
  constexpr int CcPerBlock = 4;   // output channels per block
  constexpr int R          = Cin * KH * KW; // reduction length per out-channel

  const int tid    = threadIdx.x;
  const int n      = blockIdx.z;
  const int c_base = blockIdx.y * CcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Memory strides (NCHW contiguous)
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // Global tensors as CuTe tensors
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Weights laid out as (Cout, Cin*KH*KW), row-major
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, R),
      make_stride(R, Int<1>{})
  );

  // Shared memory staging of the filter slices for this block's channels
  __shared__ T sW_raw[CcPerBlock * R];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<R>{}),
      make_stride(Int<R>{}, Int<1>{})
  );

  // Cooperative load of weights into shared memory
  for (int r = tid; r < R; r += Threads) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      sW(cc, r) = (c < Cout) ? mW(c, r) : T(0);
    }
  }
  __syncthreads();

  // Precompute output pixel coordinates handled by this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, initialized with bias
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = (B != nullptr && c < Cout) ? (float)B[c] : 0.0f;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Main convolution loop over the (fully unrolled) reduction dimension
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (p_idx[i] >= P_total) continue;

    const int ih0 = oh_arr[i] * stride - padding;
    const int iw0 = ow_arr[i] * stride - padding;

    int r = 0;
    #pragma unroll
    for (int c = 0; c < Cin; ++c) {
      #pragma unroll
      for (int kh = 0; kh < KH; ++kh) {
        const int ih = ih0 + kh;
        const bool hv = ((unsigned)ih < (unsigned)H);
        #pragma unroll
        for (int kw = 0; kw < KW; ++kw, ++r) {
          const int iw = iw0 + kw;
          if (hv && ((unsigned)iw < (unsigned)Win)) {
            const float xv = (float)mX(c, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              acc[cc][i] += xv * (float)sW(cc, r);
            }
          }
        }
      }
    }
  }

  // Epilogue: store results
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    const int c = c_base + cc;
    if (c >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      const int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");

  const int64_t N   = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t H   = x.size(2);
  const int64_t Win = x.size(3);

  const int64_t Cout = w.size(0);
  TORCH_CHECK(Cin == 3, "This kernel expects Cin == 3");
  TORCH_CHECK(w.size(1) == 3 && w.size(2) == 11 && w.size(3) == 11,
              "This kernel expects weight shape [Cout, 3, 11, 11]");
  if (b.has_value()) {
    TORCH_CHECK(b.value().dim() == 1 && b.value().size(0) == Cout,
                "bias must be [Cout]");
  }
  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");

  const int K = 11;
  const int64_t Hout = (H + 2 * padding - K) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 4;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_11x11_kernel<float, 3, 11, 11><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)H, (int)Win,
      (int)Cout,
      stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_11x11_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv_ext = load_inline(
    name="cute_conv2d_11x11_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv2d(3 -> 96, kernel_size=11, stride=4, padding=2) implemented with a
    single custom cooperative-tiled CUDA kernel written with CuTe.
    """
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels,
                        self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

