  // Global tensors as CuTe tensors
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Weights laid out as (Cout, Cin*KH*KW), row-major
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, R),
      make_stride(R, Int<1>{})
  );

  // Shared memory staging of the filter slices for this block's channels
  __shared__ T sW_raw[CcPerBlock * R];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<R>{}),
      make_stride(Int<R>{}, Int<1>{})
  );

  // Cooperative load of weights into shared memory
  for (int r = tid; r < R; r += Threads) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      sW(cc, r) = (c < Cout) ? mW(c, r) : T(0);
    }
  }
  __syncthreads();

  // Precompute output pixel coordinates handled by this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, initialized with bias
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = (B != nullptr && c < Cout) ? (float)B[c] : 0.0f;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Main convolution loop over the (fully unrolled) reduction dimension
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (p_idx[i] >= P_total) continue;

    const int ih0 = oh_arr[i] * stride - padding;
    const int iw0 = ow_arr[i] * stride - padding;

    int r = 0;
    #pragma unroll
    for (int c = 0; c < Cin; ++c) {
      #pragma unroll
      for (int kh = 0; kh < KH; ++kh) {
        const int ih = ih0 + kh;
        const bool hv = ((unsigned)ih < (unsigned)H);
        #pragma unroll
        for (int kw = 0; kw < KW; ++kw, ++r) {
          const int iw = iw0 + kw;
          if (hv && ((unsigned)iw < (unsigned)Win)) {
            const float xv = (float)mX(c, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              acc[cc][i] += xv * (float)sW(cc, r);
            }
          }
        }
      }
    }
  }

  // Epilogue: store results
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    const int c = c_base + cc;
    if (c >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      const int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");

  const int64_t N   = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t H   = x.size(2);
  const int64_t Win = x.size(3);

  const int64_t Cout = w.size(0);
  TORCH_CHECK(Cin == 3, "This kernel expects Cin == 3");
  TORCH_CHECK(w.size(1) == 3 && w.size(2) == 11 && w.size(3) == 11,
              "This kernel expects weight shape [Cout, 3, 11, 11]");
  if (b.has_value()) {
    TORCH_CHECK(b.value().dim() == 1 && b.value().size(0) == Cout,
                "bias must be [Cout]");
  }
  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");

  const int K = 11;
  const int64_t Hout = (H + 2 * padding - K) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 4;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_11x11_kernel<float, 3, 11, 11><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)H, (int)Win,
      (int)Cout,
      stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_11x11_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
